pub struct Node { x: Cell<f64>, dirty: Cell<bool>, world: RefCell<Option<World>> }
impl Node {
    fn move_by(&self, dx: f64) { self.x.set(self.x.get() + dx); self.dirty.set(true); }

    fn world(&self) -> World {
        if self.dirty.get() {                       // recompute once
            *self.world.borrow_mut() = Some(compute(self.x.get()));
            self.dirty.set(false);
        }
        self.world.borrow().clone().unwrap()
    }
}

