pub struct Node { x: Mutex<f64>, dirty: AtomicBool, world: Mutex<Option<World>> }
fn world(&self) -> World {
    if self.dirty.load(Ordering::Acquire) {              // cheap dirty check
        let mut slot = self.world.lock().unwrap();
        if self.dirty.load(Ordering::Acquire) {
            *slot = Some(compute(*self.x.lock().unwrap()));   // publish
            self.dirty.store(false, Ordering::Release);       // then clear
        }
    }
    self.world.lock().unwrap().clone().unwrap()
}
